const body = $json;
if (body.status !== 'converted' || !body.markdown || !body.metadata?.source_sha256 || Number(body.metadata?.page_count) < 1) {
  throw new Error('EXTRACTION: conversao PDF para Markdown invalida');
}
const source = $('Google Drive - Search input PDFs').item.json;
return [{ json: { ...body, source_document_id: source.id, source_filename: source.name || body.metadata.source_filename, markdown_file_name: (source.name || 'documento.pdf').replace(/\.pdf$/i, '.md') } }];

const content = Buffer.from($json.markdown, 'utf8');
const binary = await this.helpers.prepareBinaryData(content, $json.markdown_file_name, 'text/markdown');
return [{ json: $json, binary: { data: binary } }];

const source = $('Validate Markdown').item.json;
const pageCount = Number(source.metadata?.page_count || 0);
let analysisMarkdown = source.markdown;
let analysisScope = { type: 'full_document', page_count: pageCount };
const warnings = Array.isArray(source.warnings) ? [...source.warnings] : [];
if (pageCount > 20) {
  const pages = [71, 72, 73, 74, 75, 79];
  const sections = pages.map((page) => {
    const match = source.markdown.match(new RegExp('^## Página ' + page + '\n([\s\S]*?)(?=^## Página |$)', 'm'));
    return match ? '## Página ' + page + '\n' + match[1].trim() : '';
  }).filter(Boolean);
  if (sections.length) {
    analysisMarkdown = sections.join('\n\n');
    analysisScope = { type: 'targeted_pages', page_count: pageCount, pages, reason: 'documento extenso; páginas de referência para homologação' };
    warnings.push('analise IA limitada às páginas de referência 71-75 e 79; revisão humana obrigatória');
  }
}
return [{ json: { ...source, analysis_markdown: analysisMarkdown, analysis_scope: analysisScope, warnings } }];

const source = $json;
const pageCount = Number(source.metadata?.page_count || 0);
if (pageCount <= 20) return [{ json: source }];
const pages = [71, 72, 73, 74, 75, 79];
const sections = pages.map((page) => {
  const match = source.markdown.match(new RegExp('^## .+ ' + page + '\r?\n([\s\S]*?)(?=^## .+ \d+\r?\n|(?![\s\S]))', 'm'));
  return match ? '## Pagina ' + page + '\n' + match[1].trim() : '';
}).filter(Boolean);
if (!sections.length) return [{ json: source }];
return [{ json: { ...source, analysis_markdown: sections.join('\n\n'), analysis_scope: { type: 'targeted_pages', page_count: pageCount, pages, reason: 'documento extenso; páginas de referência para homologação' }, warnings: [...(source.warnings || []), 'analise IA limitada às páginas de referência 71-75 e 79; revisão humana obrigatória'] } }];

const source = $json;
const pageCount = Number(source.metadata?.page_count || 0);
if (pageCount <= 20) return [{ json: source }];
const wanted = new Set([71, 72, 73, 74, 75, 79]);
const lines = String(source.markdown || '').split(/\r?\n/);
const sections = [];
let currentPage = null;
let buffer = [];
const flush = () => { if (currentPage !== null && wanted.has(currentPage)) sections.push(buffer.join('\n').trim()); };
for (const line of lines) {
  const match = line.match(/^## .+ (\d+)\s*$/);
  if (match) { flush(); currentPage = Number(match[1]); buffer = [line]; } else if (currentPage !== null) buffer.push(line);
}
flush();
if (!sections.length) return [{ json: { ...source, warnings: [...(source.warnings || []), 'paginas de referencia nao localizadas; analise humana obrigatoria'] } }];
return [{ json: { ...source, analysis_markdown: sections.join('\n\n'), analysis_scope: { type: 'targeted_pages', page_count: pageCount, pages: [...wanted], reason: 'documento extenso; páginas de referência para homologação' }, warnings: [...(source.warnings || []), 'analise IA limitada às páginas de referência 71-75 e 79; revisão humana obrigatória'] } }];

const raw = $json.response;
if (!raw) throw new Error('IA: Ollama retornou resposta vazia');
let analysis;
try { analysis = JSON.parse(raw); } catch (error) { throw new Error('VALIDACAO: resposta do Ollama nao e JSON valido'); }
if (!analysis || typeof analysis !== 'object' || Array.isArray(analysis)) throw new Error('VALIDACAO: resposta do Ollama deve ser um objeto JSON');
const missingDocument = !analysis.documento || typeof analysis.documento !== 'object' || Array.isArray(analysis.documento);
if (missingDocument) analysis.documento = {};
const requiredArrays = ['medicamentos_deferidos','medicamentos_indeferidos','suplementos_deferidos','suplementos_indeferidos','estudos_clinicos_deferidos','estudos_clinicos_indeferidos','outros_atos','exigencias','pendencias','categorias_nao_localizadas','evidencias_insuficientes','contradicoes','avisos'];
for (const field of requiredArrays) if (!Array.isArray(analysis[field])) analysis[field] = [];
if (missingDocument) { analysis.evidencias_insuficientes.push({ descricao: 'A resposta da IA nao apresentou o objeto regulatorio esperado; validar manualmente contra as paginas de origem.', paginas_origem: [] }); analysis.revisao_humana = { necessaria: true, motivos: ['estrutura regulatoria ausente na resposta da IA'] }; }
if (typeof analysis.revisao_humana === 'boolean') analysis.revisao_humana = { necessaria: analysis.revisao_humana, motivos: [] };
if (!analysis.revisao_humana || typeof analysis.revisao_humana !== 'object') analysis.revisao_humana = { necessaria: false, motivos: [] };
return [{ json: { ...$json, response: JSON.stringify(analysis) } }];

const raw = $json.response;
if (!raw) throw new Error('IA: Ollama retornou resposta vazia');
let analysis;
try { analysis = JSON.parse(raw); } catch (error) { throw new Error('VALIDACAO: resposta do Ollama nao e JSON valido'); }
const pageBuckets = Object.values(analysis.documento || {}).filter((page) => page && typeof page === 'object' && !Array.isArray(page));
const flatten = (field) => pageBuckets.flatMap((page) => Array.isArray(page[field]) ? page[field] : []);
const categories = ['medicamentos_deferidos','medicamentos_indeferidos','suplementos_deferidos','suplementos_indeferidos','estudos_clinicos_deferidos','estudos_clinicos_indeferidos','outros_atos'];
for (const category of categories) {
  const nested = flatten(category);
  if (category === 'outros_atos') {
    nested.push(...flatten('outras_atos'));
    nested.push(...(Array.isArray(analysis.outros_atos) ? analysis.outros_atos : []));
    nested.push(...(Array.isArray(analysis.cancelados) ? analysis.cancelados.map((item) => ({ ...item, status: 'cancelado' })) : []));
    nested.push(...(Array.isArray(analysis.tipo_produto_relacionado) ? analysis.tipo_produto_relacionado.map((item) => ({ ...item, tipo_produto_relacionado: 'dispositivo' })) : []));
  }
  analysis[category] = nested;
}
for (const field of ['exigencias','pendencias','categorias_nao_localizadas','evidencias_insuficientes','contradicoes','avisos']) if (!Array.isArray(analysis[field])) analysis[field] = [];
if (typeof analysis.revisao_humana === 'boolean') analysis.revisao_humana = { necessaria: analysis.revisao_humana, motivos: [] };
if (!analysis.revisao_humana || typeof analysis.revisao_humana !== 'object') analysis.revisao_humana = { necessaria: false, motivos: [] };
for (const category of categories) for (const item of analysis[category]) if (item && item.pagina_origem && !item.paginas_origem?.length && !item.paginas?.length && !item.evidencias?.length) item.paginas_origem = [item.pagina_origem];
const required = ['documento', ...categories, 'exigencias','pendencias','categorias_nao_localizadas','evidencias_insuficientes','contradicoes','avisos','revisao_humana'];
for (const field of required) if (!(field in analysis)) throw new Error('VALIDACAO: campo obrigatorio ausente: ' + field);
const reasons = [];
if (analysis.evidencias_insuficientes.length) reasons.push('evidencia insuficiente');
if (analysis.contradicoes.length) reasons.push('contradicao');
if (analysis.revisao_humana.necessaria) reasons.push('revisao humana solicitada');
for (const category of categories) for (const item of analysis[category]) if (!item.paginas_origem?.length && !item.paginas?.length && !item.evidencias?.length) reasons.push('item sem evidencia de pagina');
const confidence_status = analysis.contradicoes.length ? 'inconclusivo' : reasons.length ? 'baixa_confianca' : 'aceitavel';
analysis.controle_confianca = { status: confidence_status, motivos: [...new Set(reasons)] };
const source = $('Validate Markdown').item.json;
return [{ json: { ...source, analysis, confidence_status, markdown_file_id: $('Google Drive - Upload Markdown').item.json.id } }];

const report = $('Report Renderer').item;
const analysis = $('Validate and classify analysis').item.json;
return [{ json: { ...$json, confidence_status: analysis.confidence_status, source_document_id: analysis.source_document_id }, binary: report.binary }];

const context = $('Validate Markdown').item.json;
const raw = $json.already_processed;
const alreadyProcessed = raw === true || raw === 't' || raw === 'true' || raw === 1 || raw === '1';
return [{ json: { ...context, already_processed: alreadyProcessed } }];
